L(OA16, 5,
  mat=MAT_DATOS,
  use="Aprenderé a escribir una evaluación crítica de un gráfico: decir qué muestra, qué problemas tiene y qué conclusión es razonable.",
  prior=["Sé detectar ejes truncados y escalas desiguales.", "Sé calcular el cambio porcentual."],
  explain=[
      "Una evaluación crítica tiene cuatro partes. Primero, describe lo que muestra el gráfico con palabras neutras. Segundo, revisa su construcción: escala, ejes, rótulos, fuente y tamaño de la muestra. Tercero, calcula con los datos para comprobar lo que parece. Cuarto, escribe una conclusión que no diga más de lo que los datos permiten.",
      "Hay que cuidar el lenguaje. Un título como «Las ventas se disparan» es una opinión; «Las ventas pasaron de 50 a 52» es una descripción. También hay que desconfiar de las conclusiones sobre causas: un gráfico que muestra dos cosas juntas no demuestra que una cause la otra. Y los resultados de pocas personas no se pueden generalizar a miles.",
      "Para comunicar bien, usa frases con evidencia: «El eje parte en 48, por lo que la barra de después parece el doble que la de antes; el cambio real es de 4 %». Termina con una recomendación, como pedir la fuente o mostrar el eje completo. Una evaluación crítica no es decir que el gráfico es malo, sino explicar con datos qué se puede y qué no se puede concluir.",
  ],
  vocab=[("evaluación crítica", "análisis razonado de qué tan confiable y claro es un gráfico"), ("generalizar", "extender lo observado en pocos casos a un grupo mucho mayor"), ("causa", "hecho que produce otro hecho"), ("evidencia", "datos que respaldan una afirmación")],
  worked=[
      ("Cartel con eje cortado", "Un cartel muestra las ventas de «Antes» (50) y «Después» (52) con el eje partiendo en 48, el título «¡Las ventas se disparan!» y sin fuente. Evalúalo.", ["Describe: las ventas pasaron de 50 a 52.", "Revisa: el eje parte en 48, no en 0; el título es una opinión; falta la fuente.", "Calcula: (52 − 50) ÷ 50 × 100 = 4 %; las barras visibles miden 2 y 4, o sea que parecen el doble."], "El aumento real es de 4 %; el cartel lo exagera y no cita la fuente"),
      ("Encuesta pequeña", "Un afiche dice «El 70 % prefiere el producto X», y la encuesta fue a 10 personas. ¿Cuántas personas son y se puede generalizar?", ["70 % de 10 = 10 × 70 ÷ 100 = 7 personas.", "Con 10 personas no es seguro hablar de lo que prefieren miles."], "7 personas; no se puede generalizar con tan pocos datos"),
  ],
  mist=[
      ("Escribir solo «el gráfico es malo» sin decir por qué.", "Una crítica necesita evidencia: el dato o el elemento que falla.", "Nombra el problema (eje, escala, fuente) y calcula con los datos."),
      ("Afirmar que una cosa causa otra porque aparecen juntas en un gráfico.", "El gráfico muestra relación, no causa.", "Escribe «se observa que aparecen juntas», no «causa»."),
  ],
  R=[arith("Las ventas pasan de 50 a 52. ¿Cuál es el cambio porcentual?", "(52-50)*100//50", "El cambio es 2 sobre 50.", " %"),
     ex("¿Qué elemento de un gráfico dice de dónde provienen los datos?", "La fuente", "La fuente indica el origen de los datos."),
     ex("¿El título «Las ventas se disparan» es una descripción objetiva? Responde sí o no.", "No", "«Se disparan» es una opinión sobre el cambio.")],
  C=[arith("En un cartel, el eje parte en 48 y las ventas son 50 y 52. ¿Cuántas veces más alta parece la segunda barra?", "(52-48)//(50-48)", "Las alturas visibles son 2 y 4 unidades.", " veces"),
     ex("¿Cuál es una buena conclusión para un cartel con ventas de 50 y 52? A) Las ventas subieron 4 %, un cambio pequeño. B) Las ventas se duplicaron. C) Las ventas no cambiaron.", "A", "Es el único enunciado que coincide con el cálculo."),
     ex("Una evaluación crítica, ¿empieza describiendo lo que muestra el gráfico o dando una opinión?", "Describiendo lo que muestra", "La opinión debe apoyarse en una descripción previa.")],
  A=[arith("Un gráfico dice que el 70 % de los encuestados prefiere un producto, y se encuestó a 10 personas. ¿Cuántas personas son?", "10*70//100", "El 70 % de 10 es la cantidad de personas.", " personas"),
     ex("Con esa encuesta de 10 personas, ¿es seguro decir lo que prefieren 5.000 personas? Responde sí o no.", "No", "Una muestra tan pequeña no permite generalizar."),
     arith("Un valor pasa de 400 a 380. El eje parte en 370 y las barras miden 30 y 10. ¿Cuántas veces más baja parece la segunda?", "(400-370)//(380-370)", "Las alturas visibles son 30 y 10 unidades.", " veces")],
  Z=[ex("Un gráfico muestra que quienes usan zapatillas rojas corren más rápido y concluye que las zapatillas rojas causan la mayor velocidad. ¿Se puede asegurar la causa solo con ese gráfico? Responde sí o no.", "No", "El gráfico muestra que aparecen juntos, no que uno cause el otro."),
     ex("Marta ve un gráfico de barras y otro circular de la misma encuesta y dice que se contradicen porque se ven distintos. ¿Tiene razón? Responde sí o no.", "No", "Si usan los mismos datos, dicen lo mismo con énfasis distinto.")],
  D=[arith("Un gráfico dice que algo «subió el doble», pero los datos pasaron de 100 a 150. ¿Cuál es el aumento real en porcentaje?", "(150-100)*100//100", "El aumento es 50 sobre 100.", " %"),
     arith("Antes del taller, el promedio era de 50 puntos y después de 51 puntos. ¿Cuál es el cambio porcentual?", "(51-50)*100//50", "El cambio es 1 sobre 50.", " %")],
  ctx=[arith("Un afiche de un gimnasio dice «¡Triplicamos socios!» con barras de 300 y 360 y el eje partiendo en 280. ¿Cuál es el aumento real en porcentaje?", "(360-300)*100//300", "El aumento es 60 sobre 300.", " %")],
  chk=[ex("¿Qué conviene pedir cuando un gráfico no cita la fuente?", "La fuente de los datos", "Sin fuente no se puede comprobar el origen."),
       ex("¿Un título debe describir el dato o dar una opinión?", "Describir el dato", "Así se evita exagerar."),
       arith("Un valor pasa de 20 a 25. ¿Cuál es el cambio porcentual?", "(25-20)*100//20", "El cambio es 5 sobre 20.", " %")],
  open=("Evalúa este gráfico de ejemplo: un cartel de una tienda muestra dos barras, «Mayo» con 200 ventas y «Junio» con 210, con el eje vertical partiendo en 190, el título «¡Ventas por las nubes!» y sin fuente. Escribe cuatro frases: qué muestra, qué problemas tiene, cuál es el cambio real calculado y qué conclusión es razonable.",
        "Muestra ventas de 200 y 210. El eje parte en 190, el título es una opinión y falta la fuente. El cambio real es de 5 %. Se puede concluir que las ventas subieron un poco, no que se dispararon.",
        ["describe lo que muestra", "nombra tres problemas", "calcula el cambio real", "escribe una conclusión razonable"],
        ["cuatro frases", "cálculo del cambio"],
        ["no calcular el cambio real", "escribir solo opiniones", "afirmar causas"],
        "Pide que muestre el cálculo del 5 %. Reconoce que su conclusión no exagera."),
  reinforce="Escribe una frase neutra que reemplace el título «¡Ventas por las nubes!» para datos de 200 y 210.",
  extend="Explica por qué una encuesta de 8 personas no basta para afirmar algo sobre todo un colegio.")

L(OA16, 6,
  mat=MAT_DATOS,
  use="Aprenderé a diseñar un gráfico propio y a auditarlo con una lista de revisión, como lo haría una persona que revisa el trabajo de otra.",
  prior=["Sé construir gráficos honestos.", "Sé evaluar críticamente un gráfico."],
  explain=[
      "Diseñar un gráfico es tomar decisiones con los datos a la vista: qué pregunta responde, qué tipo de gráfico usar, qué escala poner y cómo rotularlo. Cada decisión se puede justificar. Después se audita el trabajo con una lista de revisión: ¿el eje parte en 0 en las barras?, ¿las marcas son iguales?, ¿hay rótulos con unidad?, ¿tiene título neutro y fuente?, ¿las conclusiones se apoyan en los datos?",
      "Para auditar, calcula con los números lo que el dibujo parece mostrar. Si un gráfico parece mostrar que una barra es el triple de otra, comprueba el cociente con los datos. Si los porcentajes de un circular no suman 100 %, hay un error. Anota cada hallazgo con evidencia, por ejemplo: «el eje parte en 2, así que la barra de 12 parece 10 veces la de 3, pero es 4 veces».",
      "Una buena auditoría termina con acciones: qué cambiar para que el gráfico sea honesto. No basta con decir que algo está mal; hay que decir cómo corregirlo. Y quien diseña acepta la revisión: un gráfico es mejor cuando otra persona puede revisar los datos y llegar a la misma conclusión.",
  ],
  vocab=[("auditar", "revisar un trabajo con una lista de criterios"), ("lista de revisión", "conjunto de preguntas para comprobar un gráfico"), ("hallazgo", "problema o acierto encontrado al revisar"), ("cociente", "resultado de dividir una cantidad por otra")],
  worked=[
      ("Elegir y calcular", "Las horas de lectura de la semana de cinco amigos son Ana 6, Bruno 3, Carla 9, Diego 6 y Elisa 12. ¿Qué gráfico usas para compararlos y cuántas horas leyeron en total?", ["Se comparan categorías, así que sirve un gráfico de barras.", "Total: 6 + 3 + 9 + 6 + 12 = 36 horas."], "Gráfico de barras; 36 horas en total"),
      ("Auditar un porcentaje", "En un circular con esos datos, el sector de Diego se dibuja con 90°. ¿Está correcto?", ["Diego leyó 6 de 36 horas, o sea 6 ÷ 36 = 1/6 del total.", "1/6 de 360° es 60°, no 90°."], "No: debería medir 60°"),
  ],
  mist=[
      ("Revisar un gráfico solo mirando si es bonito.", "La belleza no garantiza que sea honesto.", "Usa la lista de revisión y calcula con los datos."),
      ("Marcar un problema sin decir cómo corregirlo.", "Una auditoría útil propone cambios concretos.", "Escribe qué cambiar: por ejemplo, partir el eje en 0."),
  ],
  R=[arith("Las horas de lectura de cinco amigos son 6, 3, 9, 6 y 12. ¿Cuál es el total de horas?", "6+3+9+6+12", "Se suman las cinco cantidades.", " horas"),
     ex("Con esos datos de lectura, ¿quién leyó más: Ana (6), Bruno (3), Carla (9), Diego (6) o Elisa (12)?", "Elisa", "Su valor de 12 horas es el mayor."),
     arith("Con la escala de 1 cm por 3 horas, ¿cuánto mide la barra de Carla, que leyó 9 horas?", "9//3", "Se divide el valor por las horas de cada centímetro.", " cm")],
  C=[ex("Un eje va de 0 a 12 con marcas cada 3 unidades. ¿Cuántas marcas tiene, contando el 0?", "5", "Las marcas son 0, 3, 6, 9 y 12."),
     ex("Las horas de lectura son Ana 6, Bruno 3, Carla 9, Diego 6 y Elisa 12. ¿Quién tendría la barra más corta?", "Bruno", "Su valor de 3 horas es el menor."),
     ex("Las horas ordenadas son 3, 6, 6, 9 y 12. ¿Cuál es la mediana?", "6", "El dato central de cinco datos ordenados es el tercero.")],
  A=[ex("Un diseño tiene el eje partiendo en 0 con marcas cada 3 unidades, no tiene rótulos y su título es «Elisa lee muchísimo». ¿Cuántos defectos tiene de estos tres: eje que no parte en 0, falta de rótulos y título subjetivo?", "2", "El eje está bien; faltan los rótulos y el título es una opinión."),
     arith("Con las horas de lectura 6, 3, 9, 6 y 12 (total 36), ¿cuántos grados mide el sector de Carla (9 horas) en un circular?", "9*360//36", "9 de 36 es un cuarto del total, y un cuarto de 360° es 90°.", "°"),
     arith("Con esos mismos datos, ¿qué porcentaje del total leyó Carla (9 de 36 horas)?", "9*100//36", "Se divide 9 por 36 y se multiplica por 100.", " %")],
  Z=[ex("Un auditor dice que un gráfico es honesto porque se ve muy bonito. ¿Es un buen criterio? Responde sí o no.", "No", "La belleza no comprueba la escala ni los datos."),
     ex("En un diseño con el eje partiendo en 2, la barra de Elisa (12 horas) mide 10 unidades y la de Bruno (3 horas) mide 1. ¿Cuántas veces más alta parece la de Elisa?", "10", "Las alturas visibles son 10 y 1, aunque la diferencia real es de 4 veces.")],
  D=[arith("Con las horas 6, 3, 9, 6 y 12, ¿qué porcentaje del total (36) suman Ana, Carla y Elisa?", "(6+9+12)*100//36", "Suman 27 de 36 horas.", " %"),
     arith("Con las horas 6, 3, 9, 6 y 12, ¿cuál es el rango?", "12-3", "El rango es el máximo menos el mínimo.", " horas")],
  ctx=[ex("Quieres comparar las horas de lectura de cada uno de los cinco amigos. ¿Usarías un gráfico de barras o uno de líneas?", "De barras", "Se comparan categorías sin orden temporal.")],
  chk=[ex("¿Qué pregunta de la lista de revisión se hace sobre el eje de un gráfico de barras?", "Si parte en 0", "Un eje truncado exagera las diferencias."),
       ex("¿Qué debe incluir una auditoría además de los problemas encontrados?", "Cómo corregirlos", "Las acciones hacen útil la revisión."),
       arith("Los sectores de un circular miden 90°, 120° y 100°. ¿Cuántos grados faltan para una vuelta completa?", "360-90-120-100", "Los sectores deben sumar 360°.", "°")],
  open=("Diseña un gráfico con estos datos de ejemplo: minutos de ejercicio de una persona en 5 días, 20, 35, 15, 40 y 30. Elige el tipo de gráfico, define la escala, dibújalo con título, rótulos y fuente (por ejemplo, «registro propio»), y revisa tu trabajo con esta lista: eje desde 0, marcas iguales, rótulos con unidad, título neutro, fuente. Anota cuántos puntos de la lista cumples.",
        "Barras con eje de 0 a 50 y marcas cada 10, rótulos «día» y «minutos», título «Minutos de ejercicio por día», fuente «registro propio». Cumplo 5 de 5 puntos.",
        ["elige el gráfico y justifica", "dibuja con escala y rótulos", "completa la lista de revisión", "anota el resultado de la auditoría"],
        ["gráfico dibujado", "lista de revisión completada", "frase de resultado"],
        ["omitir rótulos o fuente", "eje que no parte en 0", "no revisar con la lista"],
        "Pide que muestre cada punto de la lista en su dibujo. Reconoce que justifique sus decisiones."),
  reinforce="Audita un gráfico de tu casa o cuaderno con la lista de cinco puntos y anota cuántos cumple.",
  extend="Escribe una versión mejorada del título de un gráfico engañoso que hayas visto, con una frase neutra y una fuente.")

